class StepTimingMiddleware extends Middleware.BaseMiddleware {
  async onStepRun({ next, ...context }) {
    const started = Date.now();
    try {
      return await next();
    } finally {
      console.log(`${context.step.id}: ${Date.now() - started}ms`);
    }
  }
}

