import { Inngest } from "inngest";
import { Middleware } from "inngest/middleware";

const middleware = new Middleware.BaseMiddleware({
  name: "transform-data",
  init() {
    return {
      onFunctionRun() {
        return {
          transformInput({ ctx, steps }) {
            return {
              ctx: { ...ctx, tenantId: ctx.event.data.tenantId },
              steps,
            };
          },
          transformOutput({ result }) {
            return {
              result: {
                ...result,
                data: { value: result.data },
              },
            };
          },
        };
      },
    };
  },
});

export const inngest = new Inngest({ id: "example", middleware: [middleware] });

"use client";

import { useRealtime } from "inngest/react";
import { pipelineChannel } from "@/inngest/channels";
import { fetchToken } from "./actions";

export default function Progress({ contentId }: { contentId: string }) {
  const { messages, connectionStatus } = useRealtime({
    channel: pipelineChannel({ contentId }),
    topics: ["status", "result"] as const,
    token: () => fetchToken(contentId),
  });

  return (
    <div>
      <p>Connection: {connectionStatus}</p>
      <p>{messages.byTopic.result?.data.output}</p>
    </div>
  );
}

